// Writes src/world/places/thailand/activities/boat-trip/map/coast.ts: the real coasts under the Krabi map (Phang Nga
// Bay, Krabi, Ao Nang, Koh Lanta), from Natural Earth 1:10m (public domain, naturalearthdata.com), the same pinned file
// the Thailand map's coasts come from (scripts/thailand-map-land.mjs). Thailand's mainland and its islands in the box
// (Phuket's east side, Koh Yao Noi and Yai, Koh Lanta Noi and Yai), each cut to the box.
//   node scripts/krabi-map-land.mjs
// It only needs running again to change the board's edges. Never drawn by hand or generated by a picture model.
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const COMMIT = 'ca96624a56bd078437bca8184e78163e5039ad19' // natural-earth-vector v5.1.2 + fixes
const FILE = 'ne_10m_admin_0_countries.geojson'
const URL_ = `https://raw.githubusercontent.com/nvkelso/natural-earth-vector/${COMMIT}/geojson/${FILE}`

const root = path.resolve(import.meta.dirname, '..')
const cache = path.join(root, 'node_modules/.cache/thailand-map')
const OUT = path.join(root, 'src/world/places/thailand/activities/boat-trip/map/coast.ts')

/** What the data covers: a little past the board on every side (degrees; the board is in map/layout.ts). */
const BOX = { lon0: 98.12, lon1: 99.38, lat0: 7.32, lat1: 8.56 }

async function source() {
  const cached = path.join(cache, FILE)
  try {
    return JSON.parse(await readFile(cached, 'utf8'))
  } catch {
    const res = await fetch(URL_)
    if (!res.ok) throw new Error(`${res.status} fetching ${URL_}`)
    const text = await res.text()
    await mkdir(cache, { recursive: true })
    await writeFile(cached, text)
    return JSON.parse(text)
  }
}

/** Sutherland-Hodgman: a ring cut to the box (the box is convex, so one pass per side). */
function clip(ring) {
  const sides = [
    [(p) => p[0] >= BOX.lon0, (a, b) => cross(a, b, 0, BOX.lon0)],
    [(p) => p[0] <= BOX.lon1, (a, b) => cross(a, b, 0, BOX.lon1)],
    [(p) => p[1] >= BOX.lat0, (a, b) => cross(a, b, 1, BOX.lat0)],
    [(p) => p[1] <= BOX.lat1, (a, b) => cross(a, b, 1, BOX.lat1)],
  ]
  let out = ring
  for (const [inside, at] of sides) {
    const src = out
    out = []
    for (let i = 0; i < src.length; i++) {
      const a = src[i]
      const b = src[(i + 1) % src.length]
      if (inside(b)) {
        if (!inside(a)) out.push(at(a, b))
        out.push(b)
      } else if (inside(a)) out.push(at(a, b))
    }
    if (!out.length) return []
  }
  return out
}
function cross(a, b, k, v) {
  const t = (v - a[k]) / (b[k] - a[k])
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}

const data = await source()
const thai = data.features.find((f) => f.properties.ADM0_A3 === 'THA')
const polys = thai.geometry.type === 'Polygon' ? [thai.geometry.coordinates] : thai.geometry.coordinates
const rings = []
for (const p of polys) {
  const ring = p[0].slice()
  if (ring.length > 1 && ring[0][0] === ring.at(-1)[0] && ring[0][1] === ring.at(-1)[1]) ring.pop()
  const cut = clip(ring)
  if (cut.length >= 3) rings.push(cut.map(([x, y]) => [Math.round(x * 1000) / 1000, Math.round(y * 1000) / 1000]))
}
// The mainland first (the biggest), then the islands, west to east.
rings.sort((a, b) => b.length - a.length)
const [main, ...islands] = rings
islands.sort((a, b) => a[0][0] - b[0][0])
const fmt = (r) => `[${r.map(([x, y]) => `[${x},${y}]`).join(',')}]`
const text = `// The real coasts under the Krabi map, [longitude, latitude] in degrees. Written by scripts/krabi-map-land.mjs from
// Natural Earth 1:10m (public domain): don't edit it by hand. Pure data.
export type LonLat = [number, number]

/** Thailand's mainland, cut to the box: Phang Nga, Krabi and down the coast toward Trang. */
// prettier-ignore
export const MAINLAND: LonLat[] = ${fmt(main)}

/** The islands in the box: Phuket's east side, Koh Yao Yai and Noi, Koh Lanta Yai and Noi. */
// prettier-ignore
export const ISLANDS: LonLat[][] = [
${islands.map((r) => `  ${fmt(r)},`).join('\n')}
]
`
await writeFile(OUT, text)
console.log(`wrote ${path.relative(root, OUT)}: mainland ${main.length} points, ${islands.length} islands`)
